package com.xdownload.mobile;
import java.io.*;
import java.net.*;
import java.time.Duration;
import java.security.cert.Certificate;
import javax.net.ssl.*;
import org.apache.commons.net.ftp.*;
/** Anonymous public files only. FTPS requires system trust, endpoint identity and same TLS peer on the data socket. */
final class FtpEngine {
 static boolean isFtp(String raw){if(raw==null)return false;String s=raw.trim().toLowerCase(java.util.Locale.ROOT);return s.startsWith("ftp://")||s.startsWith("ftps://");}
 static URI validated(String raw,boolean allowPlain)throws IOException{try{if(raw==null||raw.length()>4096)throw new IOException("Invalid FTP URL");URI u=new URI(raw.trim());String scheme=u.getScheme(),path=u.getPath();if(!("ftps".equalsIgnoreCase(scheme)||allowPlain&&"ftp".equalsIgnoreCase(scheme))||u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null||u.getPort()==0||u.getPort()>65535||path==null||path.length()>2048||!path.startsWith("/")||path.endsWith("/")||path.chars().anyMatch(Character::isISOControl))throw new IOException("Invalid or disabled public FTP URL");return u;}catch(URISyntaxException ex){throw new IOException("Invalid FTP URL");}}
 static final class VerifiedFTPS extends FTPSClient{
  VerifiedFTPS(){super("TLS",false);setTrustManager(null);setEndpointCheckingEnabled(true);setEnabledProtocols(new String[]{"TLSv1.2","TLSv1.3"});}
  @Override protected Socket _openDataConnection_(String command,String arg)throws IOException{Socket data=super._openDataConnection_(command,arg);if(data==null)return null;try{if(!(data instanceof SSLSocket)||!(_socket_ instanceof SSLSocket))throw new SSLHandshakeException("Protected FTP data channel required");Certificate[] control=((SSLSocket)_socket_).getSession().getPeerCertificates(),peer=((SSLSocket)data).getSession().getPeerCertificates();if(control.length==0||peer.length==0||!control[0].equals(peer[0]))throw new SSLHandshakeException("FTP data certificate differs from verified control peer");return data;}catch(IOException|RuntimeException ex){try{data.close();}catch(IOException ignored){}throw ex;}}
 }
 static FTPClient open(URI u)throws IOException{boolean secure="ftps".equalsIgnoreCase(u.getScheme());FTPClient c=secure?new VerifiedFTPS():new FTPClient();c.setConnectTimeout(15000);c.setDefaultTimeout(15000);c.setDataTimeout(Duration.ofSeconds(15));c.setControlEncoding("UTF-8");c.setUseEPSVwithIPv4(true);c.setIpAddressFromPasvResponse(false);c.setRemoteVerificationEnabled(true);try{c.connect(u.getHost(),u.getPort()>0?u.getPort():21);c.setSoTimeout(15000);if(!FTPReply.isPositiveCompletion(c.getReplyCode())||!c.login("anonymous","anonymous@invalid.example"))throw new IOException("Public FTP login rejected");if(secure){FTPSClient tls=(FTPSClient)c;tls.execPBSZ(0);tls.execPROT("P");}if(!c.setFileType(FTP.BINARY_FILE_TYPE))throw new IOException("FTP binary mode rejected");c.enterLocalPassiveMode();return c;}catch(IOException|RuntimeException ex){close(c);throw ex;}}
 static void close(FTPClient c){if(c!=null&&c.isConnected())try{c.disconnect();}catch(IOException ignored){}}
 static long size(FTPClient c,String path)throws IOException{String raw=c.getSize(path);try{long n=Long.parseLong(raw==null?"":raw.trim());if(n<0)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new IOException("FTP file size unavailable");}}
 static HttpEngine.Info probe(String raw,boolean plain)throws IOException{URI u=validated(raw,plain);FTPClient c=open(u);try{String path=u.getPath();return new HttpEngine.Info(HttpEngine.safeName(path.substring(path.lastIndexOf('/')+1)),"application/octet-stream",size(c,path),"","",false);}finally{close(c);}}
 static long download(String raw,boolean plain,File target,HttpEngine.Observer obs,long rate)throws IOException{URI u=validated(raw,plain);FTPClient c=open(u);try{long total=size(c,u.getPath());if(!obs.proceed())return -1;long done=0,start=System.nanoTime(),last=0;try(InputStream in=c.retrieveFileStream(u.getPath())){if(in==null)throw new IOException("FTP file unavailable");try(FileOutputStream out=new FileOutputStream(target,false)){obs.progress(0,total,"","");byte[] buf=new byte[65536];int n;while(obs.proceed()&&(n=in.read(buf))!=-1){if(n>total-done)throw new IOException("FTP file size changed");if(!obs.throttle(n))return -1;out.write(buf,0,n);done+=n;if(rate>0){long wait=(long)(done*1000000000.0/rate)-(System.nanoTime()-start);while(wait>0&&obs.proceed()){try{Thread.sleep(Math.min(200,Math.max(1,wait/1000000)));}catch(InterruptedException ex){Thread.currentThread().interrupt();return -1;}wait=(long)(done*1000000000.0/rate)-(System.nanoTime()-start);}}if(System.nanoTime()-last>350000000){obs.progress(done,total,"","");last=System.nanoTime();}}out.getFD().sync();obs.progress(done,total,"","");}}if(!obs.proceed())return -1;if(!c.completePendingCommand()||done!=total||size(c,u.getPath())!=total)throw new IOException("FTP transfer incomplete or changed size");return done;}finally{close(c);}}
}